package com.huawei.oss.wireless.experienceassuranceservice.common.impl.utils;

import com.huawei.bsp.log.OssLog;
import com.huawei.bsp.log.OssLogFactory;
import com.huawei.bsp.remoteservice.exception.ServiceException;
import com.huawei.maos.commons.deploy.EnvUtil;
import com.huawei.maos.commons.text.StringUtil;
import com.huawei.oss.rest.util.RestCaller.Builder;
import com.huawei.oss.rest.util.RestMethod;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * 实例ID查询工具类
 *
 * @since 2025/09/09
 */
public class InstanceUtils {
    private static final OssLog LOGGER = OssLogFactory.getLogger(InstanceUtils.class);

    private static final String INSTANCE_ONLY_POLICY = "instanceOnly";

    private static final String BACKEND_LIST_POLICY_HEADER = "XX-Backend-List-Policy";

    private static final String BACKEND_LIST_HEADER = "Xx-Backend-List";

    private static final String ALL_INSTANCES_PREFIX = "all=";

    private static final String POD_NAME_ENV = "POD_NAME";

    private static final String INSTANCE_ID_SEPARATOR = ",";

    private static final String INSTANCE_NAME_SEPARATOR = "-";

    private static final String POLICY_URL = "/rest/oss/inner/experienceassurance/v1/policy";

    /**
     * 查询所有实例ID
     *
     * @return 实例ID列表
     */
    public static List<Integer> queryAllInstanceIds() {
        try {
            Builder response = new RestCaller.Builder(RestMethod.POST.name(), POLICY_URL)
                .header(BACKEND_LIST_POLICY_HEADER, INSTANCE_ONLY_POLICY)
                .call();
            Map<String, String> respHeaders = response.headers();
            String backendList = getBackendList(respHeaders);
            if (StringUtil.isEmpty(backendList)) {
                LOGGER.debug("Backend list is empty");
                return Collections.emptyList();
            }
            if (!backendList.startsWith(ALL_INSTANCES_PREFIX)) {
                LOGGER.debug("Backend list does not start with all=");
                return Collections.emptyList();
            }
            String instancesStr = backendList.substring(ALL_INSTANCES_PREFIX.length());
            String[] instanceNames = instancesStr.split(INSTANCE_ID_SEPARATOR);
            List<Integer> instanceIds = new ArrayList<>();
            for (String instanceName : instanceNames) {
                String trimmedName = instanceName.trim();
                if (StringUtil.isEmpty(trimmedName)) {
                    continue;
                }
                Optional<Integer> instanceId = parseInstanceId(trimmedName);
                instanceId.ifPresent(instanceIds::add);
            }
            return instanceIds;
        } catch (ServiceException e) {
            LOGGER.error("Failed to query all instance ids due to ServiceException", e);
            return Collections.emptyList();
        } catch (Exception e) {
            LOGGER.error("Failed to query all instance ids", e);
            return Collections.emptyList();
        }
    }

    /**
     * 从响应头Map中获取BackendList值���不区分大小写匹配键）
     *
     * @param respHeaderMap 响应头Map
     * @return BackendList值，不存在则返回空字符串
     */
    public static String getBackendList(Map<String, String> respHeaderMap) {
        if (respHeaderMap == null) {
            return "";
        }
        for (Map.Entry<String, String> entry : respHeaderMap.entrySet()) {
            if (BACKEND_LIST_HEADER.equalsIgnoreCase(entry.getKey())) {
                String value = entry.getValue();
                return value != null ? value : "";
            }
        }
        return "";
    }

    /**
     * 查询当前实例ID
     *
     * @return 当前实例ID
     */
    public static Optional<Integer> queryCurrentInstanceId() {
        String podName = EnvUtil.getEnv(POD_NAME_ENV);
        if (StringUtil.isEmpty(podName)) {
            return Optional.empty();
        }
        return parseInstanceId(podName);
    }

    /**
     * 解析实例名称，提取整数ID
     *
     * @param instanceName 实例名称，格式如 service-b-1
     * @return 解析后的整数ID
     */
    public static Optional<Integer> parseInstanceId(String instanceName) {
        if (StringUtil.isEmpty(instanceName)) {
            return Optional.empty();
        }
        String[] parts = instanceName.split(INSTANCE_NAME_SEPARATOR);
        if (parts.length == 0) {
            return Optional.empty();
        }
        String lastPart = parts[parts.length - 1];
        if (StringUtil.isEmpty(lastPart)) {
            return Optional.empty();
        }
        try {
            return Optional.of(Integer.parseInt(lastPart));
        } catch (NumberFormatException e) {
            return Optional.empty();
        }
    }
}
