                .header(BACKEND_LIST_POLICY_HEADER, INSTANCE_ONLY_POLICY)
                .call();
            Map<String, String> respHeaders = restCaller.headers();
            String backendList = getBackendList(respHeaders);
            if (StringUtil.isEmpty(backendList)) {
                LOGGER.debug("Backend list is empty");
                return Collections.emptyList();
            }
            if (!backendList.startsWith(ALL_INSTANCES_PREFIX)) {
                LOGGER.debug("Backend list does not start with all=");
                return Collections.emptyList();
            }
            String instancesStr = backendList.substring(ALL_INSTANCES_PREFIX.length());
            String[] instanceNames = instancesStr.split(INSTANCE_ID_SEPARATOR);
            List<Integer> instanceIds = new ArrayList<>();
            for (String instanceName : instanceNames) {
                String trimmedName = instanceName.trim();
                if (StringUtil.isEmpty(trimmedName)) {
                    continue;
                }
                Optional<Integer> instanceId = parseInstanceId(trimmedName);
                instanceId.ifPresent(instanceIds::add);
            }
            return instanceIds;
        } catch (ServiceException e) {
            LOGGER.error("Failed to query all instance ids due to ServiceException", e);
            return Collections.emptyList();
        } catch (Exception e) {
            LOGGER.error("Failed to query all instance ids", e);
            return Collections.emptyList();
        }
    }

    /**
     * 从响应头Map中获取BackendList值（不区分大小写匹配键）
     *
     * @param respHeaderMap 响应头Map
     * @return BackendList值，不存在则返回空字符串
     */
    private static String getBackendList(Map<String, String> respHeaderMap) {
        if (respHeaderMap == null) {
            return "";
        }
        for (Map.Entry<String, String> entry : respHeaderMap.entrySet()) {
            if (BACKEND_LIST_HEADER.equalsIgnoreCase(entry.getKey())) {
                String value = entry.getValue();
                return value != null ? value : "";
            }
        }
        return "";
    }

    /**
     * 查询当前实例ID
     *
     * @return 当前实例ID
     */
    public static Optional<Integer> queryCurrentInstanceId() {
        String podName = EnvUtil.getEnv(POD_NAME_ENV);
        if (StringUtil.isEmpty(podName)) {
            return Optional.empty();
        }
        return parseInstanceId(podName);
    }

    /**
     * 解析实例名称，提取整数ID
     *
     * @param instanceName 实例名称，格式如 service-b-1
     * @return 解析后的整数ID
     */
    private static Optional<Integer> parseInstanceId(String instanceName) {
        if (StringUtil.isEmpty(instanceName)) {
            return Optional.empty();
        }
        String[] parts = instanceName.split(INSTANCE_NAME_SEPARATOR);
        if (parts.length == 0) {
            return Optional.empty();
        }
        String lastPart = parts[parts.length - 1];
        if (StringUtil.isEmpty(lastPart)) {
            return Optional.empty();
        }
        try {
            return Optional.of(Integer.parseInt(lastPart));
        } catch (NumberFormatException e) {
            return Optional.empty();
        }
    }
}
